// Slab test: where does the segment p0→p1 enter the axis-aligned slab [lo, hi]?
// Returns { t0, t1 } with t0 ≤ t1, using ±Infinity for a slab that contains
// the start point, or null when the segment stays outside on this axis.
function slab(p, d, lo, hi) {
  if (d === 0) {
    if (p < lo || p > hi) return null;
    return { t0: -Infinity, t1: Infinity };
  }
  let t0 = (lo - p) / d;
  let t1 = (hi - p) / d;
  if (t0 > t1) { const tmp = t0; t0 = t1; t1 = tmp; }
  return { t0, t1 };
}

// Swept circle (radius r) vs brick AABB along the segment p0→p1.
// Returns the first contact { t, x, y, face } or null.
// face: 'left' | 'right' | 'top' | 'bottom' | 'corner' (entry through the
// expanded box). t === 0 means the circle already overlaps at the start.
function sweptBrick(ball, p0, p1, brick) {
  const r = ball.r;
  const sx = slab(p0.x, p1.x - p0.x, brick.x - r, brick.x + brick.w + r);
  const sy = slab(p0.y, p1.y - p0.y, brick.y - r, brick.y + brick.h + r);
  if (!sx || !sy) return null;
  const entry = Math.max(sx.t0, sy.t0);
  const exit = Math.min(sx.t1, sy.t1);
  if (entry > exit || exit < 0 || entry > 1) return null;
  const t = Math.max(0, entry);
  let face;
  if (Math.abs(sx.t0 - sy.t0) < 1e-9) face = 'corner';
  else if (sx.t0 > sy.t0) face = p1.x - p0.x > 0 ? 'left' : 'right';
  else face = p1.y - p0.y > 0 ? 'top' : 'bottom';
  return { t, x: p0.x + (p1.x - p0.x) * t, y: p0.y + (p1.y - p0.y) * t, face };
}
