```js
function resolveBricks(state, path) {
  const { ball, bricks } = state;
  for (let i = 0; i + 1 < path.length; i++) {
    const p0 = path[i];
    const p1 = path[i + 1];
    let first = null; // earliest entry among all live bricks
    for (const brick of bricks) {
      if (!brick.alive) continue;
      const hit = sweptBrick(ball, p0, p1, brick);
      if (hit && (!first || hit.t < first.hit.t)) first = { hit, brick };
    }
    if (!first) continue;
    if (first.hit.t === 0) {
      // Already overlapping at the start of this segment (e.g. a paddle
      // teleport): eject from every brick still touched, cheapest axis first.
      separateAndScore(state);
    } else {
      const { hit, brick } = first;
      breakBrick(state, brick);
      ball.x = hit.x;
      ball.y = hit.y;
      switch (hit.face) {
        case 'left':   ball.vx = -Math.abs(ball.vx); break;
        case 'right':  ball.vx = Math.abs(ball.vx); break;
        case 'top':    ball.vy = -Math.abs(ball.vy); break;
        case 'bottom': ball.vy = Math.abs(ball.vy); break;
        case 'corner': ball.vx = -ball.vx; ball.vy = -ball.vy; break;
      }
    }
    return; // one brick bounce per frame; the rest of the path is next frame
  }
}

// Separates the ball from every brick it overlaps, breaking each one once.
// The exit axis is the one of smallest penetration (both axes on a tie).
function separateAndScore(state) {
  const { ball, bricks } = state;
  for (let i = 0; i <= bricks.length; i++) {
    let best = null;
    for (const brick of bricks) {
      if (!brick.alive || !collides(ball, brick)) continue;
      const penX = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
      const penY = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));
      const pen = Math.min(penX, penY);
      if (!best || pen < best.pen) best = { brick, penX, penY, pen };
    }
    if (!best) return;
    breakBrick(state, best.brick);
    separateFrom(state.ball, best.brick);
  }
}

// Pushes the ball out of the brick along the axis of smallest penetration and
// points the velocity of that axis away from the brick (norm preserved).
function separateFrom(ball, brick) {
  const EPS = 0.001;
  const penRight = ball.x + ball.r - brick.x;
  const penLeft = brick.x + brick.w - (ball.x - ball.r);
  const penBottom = ball.y + ball.r - brick.y;
  const penTop = brick.y + brick.h - (ball.y - ball.r);
  const penX = Math.min(penRight, penLeft);
  const penY = Math.min(penBottom, penTop);
  if (penX < penY) {
    if (penRight < penLeft) { ball.x = brick.x - ball.r - EPS; ball.vx = -Math.abs(ball.vx); }
    else { ball.x = brick.x + brick.w + ball.r + EPS; ball.vx = Math.abs(ball.vx); }
  } else if (penY < penX) {
    if (penBottom < penTop) { ball.y = brick.y - ball.r - EPS; ball.vy = -Math.abs(ball.vy); }
    else { ball.y = brick.y + brick.h + ball.r + EPS; ball.vy = Math.abs(ball.vy); }
  } else {
    const sx = penRight < penLeft ? -1 : 1;
    const sy = penBottom < penTop ? -1 : 1;
    ball.x = sx < 0 ? brick.x - ball.r - EPS : brick.x + brick.w + ball.r + EPS;
    ball.y = sy < 0 ? brick.y - ball.r - EPS : brick.y + brick.h + ball.r + EPS;
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  }
}
```

And step():

```js
export function step(state, dt) {
  const { ball, paddle } = state;
  const prev = { x: ball.x, y: ball.y };
  const path = [prev];

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
    path.push({ x: ball.x, y: ball.y });
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
    path.push({ x: ball.x, y: ball.y });
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
    path.push({ x: ball.x, y: ball.y });
  }

  // Paddle — the ball bounces off the paddle's TOP face whenever it crosses it
  // during this step (prevents tunneling on slow frames) or is caught inside
  // the paddle (prevents capture when the paddle teleports onto the ball).
  const bottom = ball.y + ball.r;
  const top = ball.y - ball.r;
  const prevBottom = prev.y + ball.r;
  const xIn = ball.x >= paddle.x && ball.x <= paddle.x + paddle.w;
  const crossedTop = prevBottom <= paddle.y && bottom >= paddle.y;
  const insidePaddle = bottom > paddle.y && top < paddle.y + paddle.h;
  if (ball.vy > 0 && xIn && (crossedTop || insidePaddle)) {
    ball.y = paddle.y - ball.r;
    path.push({ x: ball.x, y: ball.y });
    // Rebound angle from the hit point; clamped so the center never sends the
    // ball straight up (dead angle), and renormalized to the level speed.
    const rawHit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    const sign = rawHit < 0 ? -1 : 1;
    const hit = sign * Math.max(0.25, Math.min(1, Math.abs(rawHit)));
    const speed = ballSpeed(state.level);
    ball.vx = speed * 0.6 * hit;
    ball.vy = -Math.sqrt(speed * speed - ball.vx * ball.vx);
    state.combo = 0;
  }

  // Bricks: swept circle-vs-AABB along the ball's actual path (each wall or
  // paddle bounce splits the path), so no step can tunnel through a brick and
  // each pass resolves at most one brick contact per axis.
  resolveBricks(state, path);

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) return true;
  return false;
}
```

