// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the ceiling, the paddle and the bricks. Brick collision is swept
// (segment vs expanded AABB) along the ball's actual path, so no step, however
// long, can tunnel through a brick, and a pass never double-inverts on a grid
// seam. The ball's path is split at each wall/paddle bounce.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;
  const prev = { x: ball.x, y: ball.y };
  const path = [prev];

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
    path.push({ x: ball.x, y: ball.y });
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
    path.push({ x: ball.x, y: ball.y });
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
    path.push({ x: ball.x, y: ball.y });
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    path.push({ x: ball.x, y: ball.y });
    // The rebound angle depends on where the paddle was hit.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    ball.vy = -Math.abs(ball.vy);
    state.combo = 0; // touching the paddle resets the combo
  }

  // Bricks: swept circle-vs-AABB along the ball's actual path.
  resolveBricks(state, path);

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

// --- Brick collision resolution (pure, swept) ------------------------------

// Kills a brick and scores it exactly once (combo included).
function breakBrick(state, brick) {
  if (!brick.alive) return;
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);
}

// Slab test: where does the segment p0→p1 enter the axis-aligned slab [lo, hi]?
// Returns { t0, t1 } with t0 ≤ t1, using ±Infinity for a slab that already
// contains the start point, or null when the segment stays outside on that axis.
function slab(p, d, lo, hi) {
  if (d === 0) {
    if (p < lo || p > hi) return null;
    return { t0: -Infinity, t1: Infinity };
  }
  let t0 = (lo - p) / d;
  let t1 = (hi - p) / d;
  if (t0 > t1) {
    const tmp = t0;
    t0 = t1;
    t1 = tmp;
  }
  return { t0, t1 };
}

// Swept circle (radius r) vs brick AABB along the segment p0→p1.
// Returns the first contact { t, x, y, face } or null. face is the face of the
// expanded box the circle enters through ('left'|'right'|'top'|'bottom', or
// 'corner' when both axes are entered at the same instant). t === 0 means the
// circle already overlaps the brick at the start of the segment.
function sweptBrick(ball, p0, p1, brick) {
  const r = ball.r;
  const sx = slab(p0.x, p1.x - p0.x, brick.x - r, brick.x + brick.w + r);
  const sy = slab(p0.y, p1.y - p0.y, brick.y - r, brick.y + brick.h + r);
  if (!sx || !sy) return null;
  const entry = Math.max(sx.t0, sy.t0);
  const exit = Math.min(sx.t1, sy.t1);
  if (entry > exit || exit < 0 || entry > 1) return null;
  const t = Math.max(0, entry);
  let face;
  if (Math.abs(sx.t0 - sy.t0) < 1e-9) face = 'corner';
  else if (sx.t0 > sy.t0) face = p1.x - p0.x > 0 ? 'left' : 'right';
  else face = p1.y - p0.y > 0 ? 'top' : 'bottom';
  return { t, x: p0.x + (p1.x - p0.x) * t, y: p0.y + (p1.y - p0.y) * t, face };
}

// Resolves brick contacts along the recorded path: only the FIRST contact of
// the pass is resolved (one bounce per axis), which prevents the ghost
// double-inversion of a grid seam. If the ball already overlaps a brick at the
// start of a segment, it is separated from every brick it touches.
function resolveBricks(state, path) {
  const { ball, bricks } = state;
  for (let i = 0; i + 1 < path.length; i++) {
    const p0 = path[i];
    const p1 = path[i + 1];
    let first = null; // earliest entry among all live bricks
    for (const brick of bricks) {
      if (!brick.alive) continue;
      const hit = sweptBrick(ball, p0, p1, brick);
      if (hit && (!first || hit.t < first.hit.t)) first = { hit, brick };
    }
    if (!first) continue;
    if (first.hit.t === 0) {
      // Already overlapping at the segment start (e.g. the paddle teleported
      // onto the ball): eject from every brick still touched.
      separateAndScore(state);
    } else {
      const { hit, brick } = first;
      breakBrick(state, brick);
      ball.x = hit.x;
      ball.y = hit.y;
      switch (hit.face) {
        case 'left':   ball.vx = -Math.abs(ball.vx); break;
        case 'right':  ball.vx = Math.abs(ball.vx); break;
        case 'top':    ball.vy = -Math.abs(ball.vy); break;
        case 'bottom': ball.vy = Math.abs(ball.vy); break;
        case 'corner': ball.vx = -ball.vx; ball.vy = -ball.vy; break;
      }
    }
    return; // the rest of the path is handled on the next frame
  }
}

// Separates the ball from every brick it overlaps, breaking each one once.
function separateAndScore(state) {
  const { ball, bricks } = state;
  for (let i = 0; i <= bricks.length; i++) {
    let best = null;
    for (const brick of bricks) {
      if (!brick.alive || !collides(ball, brick)) continue;
      const penX = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
      const penY = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));
      const pen = Math.min(penX, penY);
      if (!best || pen < best.pen) best = { brick, penX, penY, pen };
    }
    if (!best) return;
    breakBrick(state, best.brick);
    separateFrom(state.ball, best.brick);
  }
}

// Pushes the ball out of the brick along the axis of smallest penetration
// (both axes on a tie) and points that velocity component away from the brick,
// so the ball never re-enters or sticks.
function separateFrom(ball, brick) {
  const EPS = 0.001;
  const penRight = ball.x + ball.r - brick.x;
  const penLeft = brick.x + brick.w - (ball.x - ball.r);
  const penBottom = ball.y + ball.r - brick.y;
  const penTop = brick.y + brick.h - (ball.y - ball.r);
  const penX = Math.min(penRight, penLeft);
  const penY = Math.min(penBottom, penTop);
  if (penX < penY) {
    if (penRight < penLeft) {
      ball.x = brick.x - ball.r - EPS;
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = brick.x + brick.w + ball.r + EPS;
      ball.vx = Math.abs(ball.vx);
    }
  } else if (penY < penX) {
    if (penBottom < penTop) {
      ball.y = brick.y - ball.r - EPS;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = brick.y + brick.h + ball.r + EPS;
      ball.vy = Math.abs(ball.vy);
    }
  } else {
    const sx = penRight < penLeft ? -1 : 1;
    const sy = penBottom < penTop ? -1 : 1;
    ball.x = sx < 0 ? brick.x - ball.r - EPS : brick.x + brick.w + ball.r + EPS;
    ball.y = sy < 0 ? brick.y - ball.r - EPS : brick.y + brick.h + ball.r + EPS;
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  }
}

