test('D2: side hit flips vx only and pushes the ball out horizontally', () => {
  const state = createState(1);
  state.ball = { x: 90, y: 110, r: 7, vx: 260, vy: 0 };
  state.bricks = [{ x: 100, y: 100, w: 72, h: 20, row: 0, alive: true, points: 40 }];
  step(state, 1 / 60);
  assert.equal(state.ball.vx, -260);
  assert.equal(state.ball.vy, 0, 'vertical component untouched');
  assert.ok(state.ball.x + state.ball.r <= 100, 'ball pushed back to the left of the brick');
  assert.equal(state.bricks[0].alive, false);
});

test('D2: exact corner hit inverts both vx and vy', () => {
  const state = createState(1);
  state.ball = { x: 82, y: 82, r: 7, vx: 260, vy: 260 };
  state.bricks = [{ x: 100, y: 100, w: 72, h: 20, row: 0, alive: true, points: 40 }];
  step(state, 1 / 20);
  assert.equal(state.ball.vx, -260);
  assert.equal(state.ball.vy, -260);
  assert.equal(collides(state.ball, state.bricks[0]), false);
  assert.equal(state.bricks[0].alive, false);
});

test('D3: seam between two stacked bricks causes exactly one bounce', () => {
  const state = createState(6); // speed 710
  state.ball = { x: 136, y: 190, r: 7, vx: 0, vy: -710 };
  state.bricks = [
    { x: 100, y: 132, w: 72, h: 20, row: 0, alive: true, points: 40 },
    { x: 100, y: 160, w: 72, h: 20, row: 4, alive: true, points: 40 },
  ];
  step(state, 0.05);
  assert.ok(state.ball.vy > 0, 'ball bounced down, not double-inverted through the seam');
  assert.equal(state.bricks[1].alive, false, 'bottom brick broken');
  assert.equal(state.bricks[0].alive, true, 'top brick untouched');
  assert.equal(collides(state.ball, state.bricks[0]), false);
  assert.equal(collides(state.ball, state.bricks[1]), false);
});

test('D4: ball already overlapping a brick is ejected (no sticky capture)', () => {
  const state = createState(1);
  state.ball = { x: 136, y: 169, r: 7, vx: 0, vy: -260 };
  state.bricks = [{ x: 100, y: 160, w: 72, h: 20, row: 4, alive: true, points: 40 }];
