// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the ceiling, the paddle and the bricks. Brick collision is swept
// (segment vs expanded AABB) along the ball's actual path, so no step, however
// long, can tunnel through a brick, and a pass never double-inverts on a grid
// seam. The ball's path is split at each wall/paddle bounce.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;
  const prev = { x: ball.x, y: ball.y };
  const path = [prev];

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;
  path.push({ x: ball.x, y: ball.y });

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
    path.push({ x: ball.x, y: ball.y });
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
    path.push({ x: ball.x, y: ball.y });
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
    path.push({ x: ball.x, y: ball.y });
  }

  // Paddle — the ball bounces off the paddle's TOP face whenever it crosses it
  // during this step (prevents tunneling on slow frames) or is caught inside
  // the paddle (prevents capture when the paddle teleports onto the ball).
  const bottom = ball.y + ball.r;
  const top = ball.y - ball.r;
  const prevBottom = prev.y + ball.r;
  const xIn = ball.x >= paddle.x && ball.x <= paddle.x + paddle.w;
  const crossedTop = prevBottom <= paddle.y && bottom >= paddle.y;
  const insidePaddle = bottom > paddle.y && top < paddle.y + paddle.h;
  if (ball.vy > 0 && xIn && (crossedTop || insidePaddle)) {
    ball.y = paddle.y - ball.r;
    path.push({ x: ball.x, y: ball.y });
    // The rebound angle depends on where the paddle was hit; the speed of the
    // rebound is the level speed exactly (vy derived from the conserved norm).
    // The hit factor is clamped away from zero so a dead-center hit never sends
    // the ball straight up (dead angle).
    const rawHit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    const hit = (rawHit < 0 ? -1 : 1) * Math.max(0.25, Math.min(1, Math.abs(rawHit)));
    const speed = ballSpeed(state.level);
    ball.vx = speed * 0.6 * hit;
    ball.vy = -Math.sqrt(speed * speed - ball.vx * ball.vx);
    state.combo = 0; // touching the paddle resets the combo
  }

  // Bricks: swept circle-vs-AABB along the ball's actual path.
